import{e as i,ab as o,a1 as r,m as t,r as s,p as n}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse(`{"title":"Monthly Updates [Jan] & Happy New Year!","description":"Happy New Year everyone! We've made a lot of progress this year.","frontmatter":{"title":"Monthly Updates [Jan] & Happy New Year!","description":"Happy New Year everyone! We've made a lot of progress this year.","date":"2024-01-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/jan-2024.md","filePath":"posts/jan-2024.md"}`),l={name:"posts/jan-2024.md"};function d(p,e,h,c,m,g){const a=o("Post");return r(),t("div",null,[s(a,{authors:"nbats,zinklog,Q,Kai,taskylizard"}),e[0]||(e[0]=n('<p>Hi everyone, happy new year! As we bid farewell to &#39;23, let&#39;s take a moment to reflect on the remarkable journey FMHY has had this year:</p><ul><li>We made a new website, enriched with an array of handcrafted features (by me, of course) to enhance your experience and make browsing the wiki pleasant on all devices (mobile included!).</li><li>We opened our Discord server and reached 10k members, which introduced many great new people to this community and made contribution easy.</li><li>We&#39;ve reached 250k+ members and 31 million views on Reddit!</li><li>Our FMHYedit repository oversaw an impressive 1k+ pull requests made by the community and merged over 8k commits!</li><li>This wiki has grown to be more than just a piracy index, so we felt it&#39;s about time other sections get some love. As such, we organized and separated tools sections into their own pages, which allowed us to move a lot of useful tools out of storage and make it a lot easier to discover them.</li><li>We started the debloat arc of FMHY and went from 27k links to 24k! We&#39;ve removed a lot of dead, useless, and niche links / categories, as well as re-organized a lot of sections for better clarity and easier navigation.</li></ul><p>As we enter 2024, we eagerly anticipate building on our achievements and evolving together. FMHY wouldn&#39;t be what it is today without the love and support of everyone in this community. Thank you for being an integral part of FMHY. Here&#39;s to another year of growth and success! 💙</p><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Made our own instances for both <strong><a href="https://searx.fmhy.net/" target="_blank" rel="noreferrer">SearX</a></strong> + <strong><a href="https://whoogle.fmhy.net/" target="_blank" rel="noreferrer">Whoogle</a></strong>.</p></li><li><p>Made a <a href="/posts">Posts</a> page on our site, so you can see all updates without needing Reddit. You can also follow via <a href="/feed.rss">RSS</a>.</p></li><li><p>Created a new category for <a href="/social-media-tools">Social Media Tools</a> and added subsections for popular sites that needed them (Reddit, Discord, YouTube, etc.).</p></li><li><p>Added sections for <a href="/audio#game-soundtracks">Game Soundtracks</a>, <a href="/downloading#irc-tools">IRC Tools</a>, and <a href="/developer-tools#coding-ais">Coding AIs</a>.</p></li><li><p>Split Career into subsections: <a href="/misc#remote-jobs">Remote Jobs</a>, <a href="/misc#tech-jobs">Tech Jobs</a>, <a href="/misc#startup">Startup</a>, and <a href="/misc#finance-crypto">Finance / Crypto</a>.</p></li><li><p>Split Game Mods into subsections: <a href="/gaming#mod-indexes">Mod Indexes</a> and <a href="/gaming#game-mods">Single Mods</a>.</p></li><li><p>Split News into subsections: <a href="/misc#aggregators">Aggregators</a> and <a href="/misc#tech-news">Tech News</a>.</p></li><li><p>Re-organized both <a href="/mobile#operating-systems">Android Operating Systems</a> + <a href="/mobile#app-launchers">App Launchers</a>, and moved them out of storage.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="/video#streaming-sites">Braflix</a> in Streaming Sites. Fast streams, no ads, nice UI, 4K + 1080p.</p></li><li><p>Starred <a href="/reading#ebooks">Liber3</a> in Reading Sites. Big library, nice UI, single-click downloads.</p></li><li><p>Starred <a href="/video-tools#video-players">Screenbox</a> in Video Players. Open-source, VLC-based video player with a nice UI.</p></li><li><p>Starred <a href="/social-media-tools#discord-clients">Vesktop</a> in Discord Clients. Lightweight desktop client built with Vencord.</p></li><li><p>Starred <a href="/ai#proprietary-llms">SydneyQt</a> in AI Chatbots. Jailbroken Bing AI.</p></li><li><p>Starred <a href="/mobile#foss-apks">App Manager</a> in FOSS APKs. Open-source Android app package manager.</p></li><li><p>Starred <a href="/mobile#android-device">scrcpy</a> in Android Tools. Manage mobile devices via desktop.</p></li><li><p>Starred <a href="/mobile#android-device">KernelSU</a> in Android Device. Root tool that some people prefer over Magisk.</p></li><li><p>Starred <a href="/mobile#ios-privacy">Onion Browser</a> in iOS Privacy. Recommended by Tor on their site.</p></li><li><p>Starred <a href="/gaming#homebrew">Wii Guide</a> in Homebrew.</p></li><li><p>Starred <a href="/video-tools#video-tools-1">Video2x</a> in Video Tools. Lossless video/GIF/image upscaler.</p></li><li><p>Starred <a href="/system-tools#windows-updates">VCRedist</a> in Windows Updates. Easily download all Microsoft Visual C++ redists.</p></li><li><p>Starred <a href="/privacy#privacy-extensions">CanvasBlocker</a> in Privacy Extensions. Prevent JavaScript API fingerprinting.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed SevenGamers as they&#39;ve <a href="https://i.imgur.com/C5sgVqI.png" target="_blank" rel="noreferrer">decided to shut down</a>.</p></li><li><p>Removed YasDL as they uploaded a version of StarDock with the same malware that filecr and others have gotten removed for.</p></li><li><p>Removed Torrentz2 as they&#39;ve stopped indexing new torrents.</p></li><li><p>Unstarred LookMovie as they&#39;ve added a <a href="https://i.imgur.com/I0D9Hyt.png" target="_blank" rel="noreferrer">10-second wait</a> before videos play.</p></li><li><p>Unstarred DS4Windows in gaming tools. You can just add games to Steam and turn on PS4 controller support by right-clicking the game.</p></li><li><p>Unstarred Ideogram as it&#39;s no longer unlimited.</p></li><li><p>Removed EveryNoiseAtOnce as the dev has been <a href="https://i.imgur.com/AaIrcAc.png" target="_blank" rel="noreferrer">let go from Spotify</a>.</p></li><li><p>Removed CryptoStorm as it&#39;s <a href="https://i.imgur.com/VDlSY1T.png" target="_blank" rel="noreferrer">possibly unsafe</a>. The owner has no ties to it anymore apparently, but it&#39;s still hard to trust a company with a history this dark.</p></li><li><p>Removed our backups from NotABug. Their site goes down nearly <a href="https://i.imgur.com/Vx8Ou68.png" target="_blank" rel="noreferrer">every day</a> at this point, and it&#39;s become a nightmare to keep 25 wiki pages updated there. If they ever fix their issues we may bring it back.</p></li></ul>',11))])}const y=i(l,[["render",d]]);export{u as __pageData,y as default};
